insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('bed5c2d5-d6ed-499a-b109-02485f01b8be', 'a1100036-e6b9-4770-96eb-2a27454008b5', $$nitrobenzeenproces — reactie 1 en 2$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2025-ii-bacterien-maken-aniline-uit-suiker-context1.png$$,
   $$Aniline (C₆H₅NH₂) is een grondstof voor onder andere schuimrubber. In 2022 werd 9,4 miljoen ton aniline geproduceerd. Het meest gebruikte proces voor de productie van aniline is het nitrobenzeenproces. Het nitrobenzeenproces verloopt in twee stappen:
Stap 1: Benzeen (C₆H₆) reageert met geconcentreerd salpeterzuur tot nitrobenzeen (C₆H₅NO₂) en water. Als katalysator wordt geconcentreerd zwavelzuur gebruikt.
C₆H₆ + HNO₃ → C₆H₅NO₂ + H₂O (reactie 1)
Stap 2: Nitrobenzeen wordt met behulp van waterstof omgezet tot aniline en water. Dit gebeurt bij een temperatuur van 200 °C tot 300 °C in aanwezigheid van een tweede katalysator.
C₆H₅NO₂ + 3 H₂ → C₆H₅NH₂ + 2 H₂O (reactie 2)
Het hele proces kan met één vergelijking worden weergegeven.$$, 'inline'),
  ('119e6973-d42e-4aa6-abea-35b0676c26ef', 'a1100036-e6b9-4770-96eb-2a27454008b5', $$groene chemie — uitgangspunten 7 en 12$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2025-ii-bacterien-maken-aniline-uit-suiker-context1b.png$$,
   $$Het nitrobenzeenproces is niet “groen” te noemen. Gebruik van de stof benzeen past niet bij uitgangspunt 7 van de groene chemie, omdat benzeen een bestanddeel is van aardolie. Gebruik van geconcentreerd salpeterzuur past niet bij uitgangspunt 12 van de groene chemie.$$, 'inline'),
  ('8907a151-a21d-4e93-a8f9-f6b73717df76', 'a1100036-e6b9-4770-96eb-2a27454008b5', $$figuur 1 — blokschema fabriek en anthraniline$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2025-ii-bacterien-maken-aniline-uit-suiker-context2.png$$,
   $$In Duitsland heeft Covestro een fabriek gebouwd die gebruik maakt van genetisch aangepaste bacteriën voor de productie van aniline. Figuur 1a toont een onvolledig blokschema voor deze fabriek. In een reactor die bacteriën bevat (R1), wordt een oplossing van onder andere glucose en ammoniumchloride (NH₄Cl) ingevoerd als voedingsstof voor de bacteriën. Bacteriën zetten deze stoffen om tot anthraniline (figuur 1b).
figuur 1: 1a. onvolledig blokschema — oplossing van glucose en NH₄Cl gaat naar R1, R1 naar S1, S1 geeft water/anthraniline/wateroplosbare bijproducten door naar R2, en S1 wisselt bacteriën uit met R1. 1b. structuurformule van anthraniline: een benzeenring met een NH₂-groep en een COOH-groep op naburige C-atomen.$$, 'inline'),
  ('722c735e-4bc7-4181-8bea-efa7918a2120', 'a1100036-e6b9-4770-96eb-2a27454008b5', $$filtraat pH = 7,5$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2025-ii-bacterien-maken-aniline-uit-suiker-context3.png$$,
   $$Na een bepaalde tijd zijn de voedingsstoffen omgezet en wordt de inhoud van de reactor gefiltreerd (S1). Het residu bestaat uit bacteriën die kunnen worden hergebruikt. Omdat de bacteriën zich vermenigvuldigen, wordt een deel hiervan afgevoerd. In het filtraat zijn onder andere water, anthraniline en wateroplosbare bijproducten aanwezig. De pH van het filtraat is 7,5. Bij deze pH hebben moleculen anthraniline een H⁺-ion afgestaan.$$, 'inline'),
  ('929ad2bf-f17d-4ea0-a9c3-8122baf58817', 'a1100036-e6b9-4770-96eb-2a27454008b5', $$figuur 2 — extractie met dodecaan-1-ol$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2025-ii-bacterien-maken-aniline-uit-suiker-context4.png$$,
   $$Het filtraat wordt geleid naar een tweede reactor (R2). Bij een temperatuur van 160 °C wordt anthraniline volledig omgezet tot aniline en koolstofdioxide. In R2 wordt koolstofdioxide afgescheiden van het mengsel van water, aniline en wateroplosbare bijproducten. Vervolgens wordt aniline in scheidingsruimte 2 (S2) gescheiden van de rest van het reactiemengsel door middel van extractie met dodecaan-1-ol. De extractie in S2 wordt uitgevoerd met dodecaan-1-ol, omdat aniline hierin beter oplost dan in water. In figuur 2 is schematisch weergegeven hoe twee moleculen dodecaan-1-ol een anilinemolecuul omringen.
figuur 2: twee dodecaan-1-ol-moleculen (lange rechte koolstofketens eindigend op -OH) omringen een anilinemolecuul (benzeenring met NH₂-groep).
Tussen moleculen aniline en dodecaan-1-ol zijn verschillende bindingstypen aanwezig.$$, 'inline'),
  ('1b576370-f591-413f-9cea-dfd78344bd6e', 'a1100036-e6b9-4770-96eb-2a27454008b5', $$vloeistoflagen water en dodecaan-1-ol$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2025-ii-bacterien-maken-aniline-uit-suiker-context5.png$$,
   $$Omdat water en dodecaan-1-ol niet mengen, ontstaan in S2 twee vloeistoflagen. De vloeistoflaag met daarin dodecaan-1-ol vormt hierbij de bovenste laag.$$, 'inline'),
  ('c6313954-6b7d-41bf-b308-8ca83d47103c', 'a1100036-e6b9-4770-96eb-2a27454008b5', $$tabel — structuurformules en kookpunten aniline en dodecaan-1-ol$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2025-ii-bacterien-maken-aniline-uit-suiker-context6.png$$,
   $$De vloeistoflaag met dodecaan-1-ol en aniline wordt in S2 afgescheiden van de laag met water en de wateroplosbare bijproducten. De laag met dodecaan-1-ol en aniline wordt gescheiden in scheidingsruimte 3 (S3). Dodecaan-1-ol wordt hergebruikt. In de tabel is informatie opgenomen over aniline en dodecaan-1-ol.
tabel: stof — structuurformule — kookpunt (°C). aniline — benzeenring met NH₂-groep — 184. dodecaan-1-ol — H₃C-(CH₂)₁₁-OH — 259.$$, 'inline'),
  ('45da9ac2-edc5-47e8-a589-fc65ac0512d3', 'a1100036-e6b9-4770-96eb-2a27454008b5', $$uitwerkbijlage vraag 4 — structuurformule anthraniline$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2025-ii-bacterien-maken-aniline-uit-suiker-context7-uitwerkbijlage.png$$,
   $$uitwerkbijlage bij vraag 4: de structuurformule van anthraniline (benzeenring met NH₂-groep en COOH-groep) is afgebeeld; de leerling moet het H-atoom omcirkelen dat bij pH = 7,5 als H⁺-ion is afgestaan.$$, 'uitwerkbijlage'),
  ('89718979-56ba-4c25-97f8-85379f063b44', 'a1100036-e6b9-4770-96eb-2a27454008b5', $$uitwerkbijlage vraag 8 — blokschema fabriek$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2025-ii-bacterien-maken-aniline-uit-suiker-context8-uitwerkbijlage.png$$,
   $$uitwerkbijlage bij vraag 8: het onvolledige blokschema van figuur 1a is nogmaals weergegeven (oplossing van glucose en NH₄Cl → R1 → S1 → anthraniline/4,5 → R2, met bacteriën-hergebruik tussen R1 en S1); de leerling moet de blokken S2 en S3 tekenen, de pijlen van de ontbrekende stofstromen bij R2, S2 en S3 tekenen, en de nummers van de stoffen (1 aniline, 2 dodecaan-1-ol, 3 koolstofdioxide, 4 water, 5 wateroplosbare bijproducten) bij de juiste pijlen noteren, inclusief hergebruik van dodecaan-1-ol.$$, 'uitwerkbijlage'),
  ('576f3b64-7956-4397-80e6-22ebf86f3b88', '96432d5c-9443-4da5-95a7-bd5967d8556a', $$Na⁺-ionen in zeewater — 470 mmol per liter$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2025-ii-zeewater-accu-context1.png$$,
   $$De huidige lithium-ionbatterij is geschikt voor de duurzame opslag van energie, maar het benodigde lithium is schaars. Daarom wordt onderzoek gedaan naar een accu die natrium-ionen gebruikt. Na⁺-ionen zijn overvloedig aanwezig in zeewater. De molariteit van de Na⁺-ionen hierin is gemiddeld 470 mmol per liter zeewater.$$, 'inline'),
  ('bab85eb7-abc1-425d-8bdc-a65ee0f33387', '96432d5c-9443-4da5-95a7-bd5967d8556a', $$figuur 1 — opladen van de zeewater-accu$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2025-ii-zeewater-accu-context2.png$$,
   $$Een accu die Na⁺-ionen uit zeewater gebruikt, wordt een zeewater-accu genoemd. Het opladen van een bepaald type zeewater-accu is in figuur 1 schematisch weergegeven.
figuur 1: schema van het opladen — een spanningsbron stuurt elektronen (e⁻) weg van de natrium-elektrode en naar de koolstofelektrode; in de cel bevindt zich oplossing A, gescheiden van het instromende/uitstromende zeewater door een membraan waardoor Na⁺-ionen van de koolstofelektrode-kant naar de natrium-elektrode-kant bewegen.$$, 'inline'),
  ('84c996f6-346c-430b-8fb0-c640a3f0542e', '96432d5c-9443-4da5-95a7-bd5967d8556a', $$oplossing A — natriumtrifluormethaansulfonaat$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2025-ii-zeewater-accu-context3.png$$,
   $$Oplossing A bevat het zout natriumtrifluormethaansulfonaat (NaCF₃SO₃). Dit zout bevat twee soorten ionen: Na⁺-ionen en trifluormethaansulfonaat-ionen.$$, 'inline'),
  ('29a0005f-bfb4-469f-a4aa-ca64292e022a', '96432d5c-9443-4da5-95a7-bd5967d8556a', $$halfreactie 1 — koolstofelektrode bij opladen$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2025-ii-zeewater-accu-context4.png$$,
   $$Bij het opladen vindt aan de natriumelektrode een halfreactie plaats waarbij Na⁺-ionen uit oplossing A worden omgezet tot natrium. Zeewater is licht basisch. Aan de koolstofelektrode reageren bij het opladen hydroxide-ionen tot zuurstof en water volgens halfreactie 1.
opladen: 4 OH⁻ → O₂ + 2 H₂O + 4 e⁻ (halfreactie 1)$$, 'inline'),
  ('ce633625-261b-4957-94e3-fc01ffe29654', '96432d5c-9443-4da5-95a7-bd5967d8556a', $$accu levert ook stroom$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2025-ii-zeewater-accu-context5.png$$,
   $$De accu kan uiteraard ook stroom leveren.$$, 'inline'),
  ('f9c3d7b7-937f-4f66-905e-e51b59fd153b', '96432d5c-9443-4da5-95a7-bd5967d8556a', $$reactie natrium met water — NaOH en H220$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2025-ii-zeewater-accu-context6.png$$,
   $$De natrium-elektrode is goed afgesloten voor water. Als toch een kleine hoeveelheid water in de elektroderuimte terechtkomt, kan water reageren met natrium. Hierbij wordt vast natriumhydroxide (NaOH) gevormd. Ook ontstaat een andere stof, hierop is gevarenzin H220 van toepassing.$$, 'inline'),
  ('f8b58695-10d6-456b-aa3b-09a3a34852e3', '96432d5c-9443-4da5-95a7-bd5967d8556a', $$halfreacties 2 en 3 — Sb₂S₃-elektrode en legering Na₃Sb$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2025-ii-zeewater-accu-context7.png$$,
   $$Vanwege de risico’s van het gebruik van natriumelektroden is onderzoek gedaan naar het gebruik van andere elektroden in zeewater-accu’s. Een van de onderzochte elektroden is een elektrode van di-antimoontrisulfide (Sb₂S₃). Deze stof reageert bij opladen met Na⁺-ionen tot het metaal antimoon (Sb) en een zout (halfreactie 2). Vervolgens worden Sb-atomen en Na⁺-ionen omgezet tot de legering Na₃Sb (halfreactie 3).
Sb₂S₃ + 6 Na⁺ + 6 e⁻ → 2 Sb + 3 Na₂S (halfreactie 2)
2 Sb + 6 Na⁺ + 6 e⁻ → 2 Na₃Sb (halfreactie 3)
In halfreactie 3 neemt een van de deeltjes elektronen op.$$, 'inline'),
  ('1f6ce974-79d8-4be9-8e11-6e6e0b843c4d', '96432d5c-9443-4da5-95a7-bd5967d8556a', $$energiedichtheid van de accu — 51 Wh per mol elektronen$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2025-ii-zeewater-accu-context8.png$$,
   $$Uit halfreacties 2 en 3 blijkt dat per mol Sb₂S₃ veel elektronen worden opgenomen. Dit is een belangrijk gegeven voor de energiedichtheid van een accu. De energiedichtheid van deze accu is de hoeveelheid energie die per kg elektrodemateriaal (Sb₂S₃) kan worden geleverd. De energiedichtheid wordt uitgedrukt in Wh kg⁻¹ (wattuur per kg). De maximale energie die deze accu per mol elektronen kan leveren, is 51 Wh.$$, 'inline'),
  ('c0904557-6951-4bfc-9e31-06f48e2ffd1a', '96432d5c-9443-4da5-95a7-bd5967d8556a', $$figuur 2 — massieve elektrode vs. naaldjes, diameter atomen$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2025-ii-zeewater-accu-context9.png$$,
   $$Een probleem met een massieve Sb₂S₃-elektrode is dat Na⁺-ionen moeilijk tot het binnenste gedeelte van de elektrode kunnen doordringen (figuur 2a). Hierdoor is de elektrode minder efficiënt. De onderzoekers hebben daarom een elektrode gemaakt waarin het Sb₂S₃ in de vorm van dunne naaldjes (figuur 2b) aanwezig is.
figuur 2: 2a. Sb₂S₃-elektrode bestaande uit een massieve staaf, met een buitenste deel waar Na⁺ wel kan doordringen en een binnenste deel waar Na⁺ niet kan doordringen. 2b. elektronenmicroscoop-opname van een Sb₂S₃-elektrode bestaande uit naaldjes, met de dikte van een naaldje aangegeven met k.
De gemiddelde diameter van de atomen in de naaldjes is 3,7 Å (1,0 Å = 0,1 nm).$$, 'inline'),
  ('fef69917-4953-4fc4-acb1-476a415ce085', '3a3a82c9-a477-4ca4-871b-8fbc2e51537d', $$stikstof als bouwstof voor planten$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2025-ii-stikstofbindende-bacterien-maken-etheen-context1.png$$,
   $$Planten halen hun voedingsstoffen uit de bodem en de lucht. Voedingsstoffen voor planten moeten onder andere het element stikstof bevatten. Zonder het element stikstof kunnen planten een bepaalde bouwstof niet aanmaken.$$, 'inline'),
  ('551df630-c19d-46dc-b9f2-aaeb35b12509', '3a3a82c9-a477-4ca4-871b-8fbc2e51537d', $$stikstofbindende bacteriën — ammoniakvorming bij kamertemperatuur$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2025-ii-stikstofbindende-bacterien-maken-etheen-context2.png$$,
   $$Planten kunnen stikstofmoleculen uit de lucht niet opnemen of omzetten. Planten nemen daarom het element stikstof op in de vorm van stikstofhoudende verbindingen. Rondom de wortels van planten kunnen stikstofbindende bacteriën voorkomen. Deze bacteriën zijn in staat om bij kamertemperatuur stikstofmoleculen om te zetten tot ammoniakmoleculen (NH₃). Als mensen daarentegen ammoniak willen maken, dan gebeurt dat in fabrieken of laboratoria bij een temperatuur van ongeveer 500 °C.$$, 'inline'),
  ('086509f7-72c7-4685-8c0a-1e4da7fccf8c', '3a3a82c9-a477-4ca4-871b-8fbc2e51537d', $$ammoniak als base — vorming ammonium-ionen$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2025-ii-stikstofbindende-bacterien-maken-etheen-context3.png$$,
   $$Planten nemen geen ammoniakmoleculen op, maar ammonium-ionen. Ammoniak is een base. Als ammoniak reageert met water, ontstaan onder andere ammonium-ionen.$$, 'inline'),
  ('4b3e11d0-4006-43df-91c5-c502a2ec7883', '3a3a82c9-a477-4ca4-871b-8fbc2e51537d', $$omzetting C₃H₈SO tot etheen — halfreactie 1$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2025-ii-stikstofbindende-bacterien-maken-etheen-context4.png$$,
   $$Stikstofbindende bacteriën gebruiken sulfaat-ionen om het aminozuur methionine te maken. Wanneer de concentratie sulfaat laag is, kunnen sommige soorten bacteriën ook op een andere manier methionine maken. Als bijproduct wordt dan etheen gevormd. Onderzoekers hebben vastgesteld dat in deze bacteriën uiteindelijk een stof met de formule C₃H₈SO wordt omgezet tot etheen. Deze omzetting is een redoxreactie.
Een van de halfreacties is hieronder onvolledig weergegeven (halfreactie 1).
C₃H₈SO → CH₃SH + C₂H₄ + H₂O (halfreactie 1)
In deze halfreactie ontbreken H⁺-ionen en elektronen.$$, 'inline'),
  ('f66ba489-671d-4e78-9a84-6435efc78aae', '3a3a82c9-a477-4ca4-871b-8fbc2e51537d', $$etheenconcentratie en wortelgroei — grenswaarde en experiment$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2025-ii-stikstofbindende-bacterien-maken-etheen-context5.png$$,
   $$De stof etheen kan problemen vormen bij het telen van gewassen. De etheen-concentratie in de bodem kan namelijk door aanwezigheid van een bacteriesoort, zoals R. rubrum, steeds hoger worden. Onderzoek heeft aangetoond dat de groei van plantenwortels wordt verstoord bij een etheen-concentratie die hoger is dan 0,1 cm³ per m³ grond. De onderzoekers hebben de etheenproductie van deze bacteriën gemeten in het laboratorium. Onder geschikte omstandigheden werd door de bacteriën in een reageerbuisje in 1 uur tijd 3·10⁻² μmol etheen gevormd.
Roos probeert zich voor te stellen wat het effect van deze hoeveelheid etheen is. Ze wil deze hoeveelheid vergelijken met de concentratie etheen waarbij de wortelgroei wordt verstoord. Ze berekent daarom het volume grond in dm³ waarbij de wortelgroei net niet wordt verstoord door 3·10⁻² μmol etheen.$$, 'inline'),
  ('f2053e35-3553-4473-8b4c-5c75115a17ed', 'af2be4cb-14d0-4ad9-abdf-4bf1a68d42d3', $$figuur 1 — mondkapje type IIR met drie lagen$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2025-ii-mondkapjes-context1.png$$,
   $$Tijdens de covid-19-pandemie werden er grote hoeveelheden mondkapjes gebruikt, zoals het mondkapje type IIR (figuur 1).
figuur 1: foto van een mondkapje type IIR met drie lagen aangegeven: laag 3 (bovenop bij de foto), laag 2 en laag 1.
Dit mondkapje bestaat uit drie lagen:
- laag 1: de buitenlaag die grote vochtdruppels tegenhoudt.
- laag 2: de middenlaag met zeer kleine poriën. Deze laag houdt kleinere vochtdruppels tegen die virusdeeltjes kunnen bevatten.
- laag 3: de binnenlaag die vocht uit de uitgeademde lucht kan opnemen.$$, 'inline'),
  ('a2bfec36-0413-4a60-a09d-58c51f90fb72', 'af2be4cb-14d0-4ad9-abdf-4bf1a68d42d3', $$figuur 2 — structuurformule polymeer A$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2025-ii-mondkapjes-context2.png$$,
   $$Lagen 1 en 2 kunnen worden gemaakt van polymeer A (figuur 2). Polymeer A is een additiepolymeer.
figuur 2: structuurformule van polymeer A — een polymeerketen ~CH₂-CH(CH₃)-CH₂-CH(CH₃)-CH₂-CH(CH₃)~, met aan elke tweede C-atoom een CH₃-zijgroep.$$, 'inline'),
  ('7e757b80-5b6e-4ac2-aeed-6768d1f7ad26', 'af2be4cb-14d0-4ad9-abdf-4bf1a68d42d3', $$polymeer A houdt water tegen, laat waterdamp door$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2025-ii-mondkapjes-context3.png$$,
   $$Lagen 1 en 2 houden druppels water tegen, maar laten waterdamp door. De losse watermoleculen in waterdamp binden namelijk niet aan polymeer A.$$, 'inline'),
  ('7ad2d2fe-c43e-4504-b342-8112a7328556', 'af2be4cb-14d0-4ad9-abdf-4bf1a68d42d3', $$hulpstof — magnesium- en stearaationen$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2025-ii-mondkapjes-context4.png$$,
   $$Bij de productie van laag 2 wordt aan polymeer A een hulpstof toegevoegd. Deze hulpstof is opgebouwd uit magnesium-ionen en stearaat-ionen (C₁₇H₃₅COO⁻).$$, 'inline'),
  ('d062220e-0539-4402-b1c5-0d77644a434a', 'af2be4cb-14d0-4ad9-abdf-4bf1a68d42d3', $$figuur 3 — productieproces laag 2 (extruder en blazen)$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2025-ii-mondkapjes-context5.png$$,
   $$Laag 2 van het mondkapje wordt geproduceerd in 2 stappen (figuur 3):
Stap 1: Polymeer A en de hulpstof worden in een extruder gemengd en verwarmd.
Stap 2: Onder invloed van een sterke warme luchtstroom wordt het vloeibare mengsel tot zeer kleine vezeltjes geblazen. Deze vezeltjes vormen laag 2.
figuur 3: schema van het proces — polymeer A en hulpstof gaan de extruder in, via een toevoerbuis naar een blaaskamer waar het mengsel geblazen wordt, vervolgens over een koelrol tot laag 2 wordt gevormd.$$, 'inline'),
  ('9bc2bb9e-2c40-4ffd-bf67-05f5d48e8f11', 'af2be4cb-14d0-4ad9-abdf-4bf1a68d42d3', $$polymeer A geschikt voor verwerking in extruder$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2025-ii-mondkapjes-context6.png$$,
   $$Een stofeigenschap van polymeer A maakt het materiaal geschikt om te verwerken in een extruder. Deze stofeigenschap kan onder andere worden verklaard uit een kenmerk op microniveau.$$, 'inline'),
  ('fac22cd1-dd63-4087-8e61-c0ab79e6e4a7', 'af2be4cb-14d0-4ad9-abdf-4bf1a68d42d3', $$figuur 4 — reactie polymeer A met zuurstof tot carboxylgroepen$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2025-ii-mondkapjes-context7.png$$,
   $$Laag 3 van het mondkapje wordt vaak ook gemaakt van polymeer A, maar polymeer A kan geen water binden. Om laag 3 waterbindende eigenschappen te geven wordt door reactie met zuurstof een deel van de polymeerketens voorzien van carboxylgroepen. In figuur 4 is de vergelijking van deze reactie onvolledig weergegeven.
figuur 4: polymeerketen ~CH₂-CH(CH₃)-CH₂-CH(CH₃)-CH₂-CH(CH₃)~ reageert met O₂ tot fragment X + H-CH(CH₃)~, waarbij de keten breekt op de aangegeven plek.
Door de reactie breekt een polymeerketen in twee fragmenten. Fragment X bevat een carboxylgroep.$$, 'inline'),
  ('80cadfdc-6363-403f-8a7b-2d02969a6fe8', 'af2be4cb-14d0-4ad9-abdf-4bf1a68d42d3', $$verbranding van mondkapjes met polymeer A — 2020$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2025-ii-mondkapjes-context8.png$$,
   $$In 2020 werden wereldwijd op een gegeven moment per dag 2,0 miljard mondkapjes met polymeer A in afvalovens verbrand.$$, 'inline'),
  ('bbe3566d-63a2-4af3-9cd5-e1c02c67b55b', '7c680bd1-f008-4134-8937-2b80ce5b52d4', $$figuur 1 — structuurformule repeterende eenheid HyZ$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2025-ii-hyaluronzuur-in-fillers-context1.png$$,
   $$Om rimpels op te vullen, kan een ‘filler’ in de huid geïnjecteerd worden. Moderne fillers bevatten vaak de polysacharide hyaluronzuur (HyZ). Volgens fabrikanten houdt je huid door het gebruik van een filler met HyZ beter water vast. Hierdoor worden rimpels opgevuld en ziet je huid er strakker uit. In figuur 1 is de structuurformule van een repeterende eenheid van HyZ weergegeven.
figuur 1: structuurformule van een repeterende eenheid van hyaluronzuur — twee aan elkaar gekoppelde suikerringen, één met een COOH-groep, de andere met een CH₂OH-groep en een NH-C(=O)-CH₃-groep (acetamidogroep).$$, 'inline'),
  ('d4d5c33d-09c6-48d2-834f-35c6f541dd92', '7c680bd1-f008-4134-8937-2b80ce5b52d4', $$waterbindend vermogen van HyZ — directe en indirecte waterstofbruggen$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2025-ii-hyaluronzuur-in-fillers-context2.png$$,
   $$HyZ heeft een zeer hoog waterbindend vermogen. Een klein deel van de gebonden watermoleculen is via waterstofbruggen direct gebonden aan HyZ. Een groter deel is niet direct gebonden, maar is via andere watermoleculen gebonden aan HyZ.$$, 'inline'),
  ('c7f1da43-99b5-4f4d-a81e-dbc28fc81545', '7c680bd1-f008-4134-8937-2b80ce5b52d4', $$1,0 gram HyZ bindt 44 gram water$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2025-ii-hyaluronzuur-in-fillers-context3.png$$,
   $$Tijdens een onderzoek is bepaald dat 1,0 gram HyZ 44 gram water kan binden.$$, 'inline'),
  ('38921f44-964e-417a-9104-62db819bf8c2', '7c680bd1-f008-4134-8937-2b80ce5b52d4', $$afbraak van HyZ door hydrolyse in ongebruikte filler$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2025-ii-hyaluronzuur-in-fillers-context4.png$$,
   $$HyZ is een polysacharide en wordt in een ongebruikte filler langzaam afgebroken door hydrolyse. Daarom kan een ongebruikte filler niet oneindig lang worden bewaard. Op de uitwerkbijlage is de vergelijking van de hydrolyse van een repeterende eenheid HyZ onvolledig weergegeven. De plaats van de hydrolyse is met een pijl aangegeven.$$, 'inline'),
  ('8eaa8806-1526-4f15-bcbb-c1ded492843e', '7c680bd1-f008-4134-8937-2b80ce5b52d4', $$figuur 2 — molaire massa HyZ in de tijd bij kamertemperatuur$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2025-ii-hyaluronzuur-in-fillers-context5.png$$,
   $$Onderzoekers hebben de hydrolyse van HyZ onderzocht. Gedurende meerdere maanden hebben de onderzoekers in een filler de gemiddelde molaire massa van HyZ gemeten. In figuur 2 zijn de onderzoeksresultaten weergegeven.
figuur 2: grafiek van de molaire massa van HyZ (g mol⁻¹, y-as van 15,0·10³ tot 17,0·10³) tegen de tijd (dagen, x-as van 0 tot 200) bij bewaring op kamertemperatuur; de molaire massa daalt van 17,0·10³ bij t=0 snel en daarna afvlakkend tot ongeveer 15,2·10³ bij t=200 dagen.
Figuur 2 toont de molaire massa van HyZ als de filler wordt bewaard bij kamertemperatuur. Op de uitwerkbijlage is figuur 2 nogmaals weergegeven.$$, 'inline'),
  ('1de132e7-48a0-4cbd-a200-814865261a0a', '7c680bd1-f008-4134-8937-2b80ce5b52d4', $$figuur 3 — HyZ-ketens met crosslinks (BDDE)$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2025-ii-hyaluronzuur-in-fillers-context6.png$$,
   $$Ook in het lichaam wordt HyZ afgebroken. Dit gebeurt onder invloed van het enzym hyaluronidase. Deze afbraak in het lichaam verloopt snel in vergelijking met buiten het lichaam. Om de enzymatische afbraak van HyZ in het lichaam tegen te gaan, wordt in een filler vaak gebruikgemaakt van HyZ waarin de ketens met crosslinks aan elkaar zijn gekoppeld (figuur 3).
figuur 3: twee repeterende eenheden van HyZ, onderling verbonden via een crosslink bestaande uit een keten van -CH₂-CH(OH)-CH₂-O-(CH₂)₄-O-CH₂-CH(OH)-CH₂- (afkomstig van de crosslinker BDDE).$$, 'inline'),
  ('cbd53933-75a2-4f58-bf5f-750e1cb87fa7', '7c680bd1-f008-4134-8937-2b80ce5b52d4', $$enzymatische afbraak verloopt niet in de crosslinks$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2025-ii-hyaluronzuur-in-fillers-context7.png$$,
   $$De enzymatische afbraak van HyZ door hyaluronidase verloopt niet in de delen van HyZ met crosslinks. De ingespoten filler behoudt hierdoor langer zijn werking.$$, 'inline'),
  ('8ff14a78-98ec-4947-8296-f77a0494eab7', '7c680bd1-f008-4134-8937-2b80ce5b52d4', $$BDDE als crosslinker — maximale concentratie$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2025-ii-hyaluronzuur-in-fillers-context8.png$$,
   $$Een stof die veel gebruikt wordt als crosslinker is BDDE. Maar deze stof is zeer reactief en kan schade aan weefsels opleveren. Er mag daarom van het niet-gereageerde BDDE maximaal 1,0·10⁻⁵ mol L⁻¹ in de filler aanwezig zijn.$$, 'inline'),
  ('f5f7bc7a-fc7b-4420-8a6f-7b9112a69452', '7c680bd1-f008-4134-8937-2b80ce5b52d4', $$afbraak BDDE-crosslink tot glycerol en butaandizuur$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2025-ii-hyaluronzuur-in-fillers-context9.png$$,
   $$In het lichaam zal het gecrosslinkte HyZ uiteindelijk toch worden afgebroken. De BDDE-crosslink wordt hierbij omgezet tot de lichaamseigen stoffen glycerol en butaandizuur.$$, 'inline'),
  ('f6bf5e24-ddba-4ab7-b48e-8065afa5d342', '7c680bd1-f008-4134-8937-2b80ce5b52d4', $$uitwerkbijlage vraag 30 — repeterende eenheid HyZ om waterstofbruggen te tekenen$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2025-ii-hyaluronzuur-in-fillers-context10-uitwerkbijlage.png$$,
   $$uitwerkbijlage bij vraag 30: de structuurformule van de repeterende eenheid van HyZ (identiek aan figuur 1) is afgebeeld; de leerling moet een watermolecuul tekenen dat via een waterstofbrug direct gebonden is aan HyZ, en een tweede watermolecuul dat via een waterstofbrug aan het eerste watermolecuul gebonden is.$$, 'uitwerkbijlage'),
  ('fdd03bad-c302-4e83-a16c-8214cbd205fc', '7c680bd1-f008-4134-8937-2b80ce5b52d4', $$uitwerkbijlage vraag 32 — onvolledige hydrolysevergelijking HyZ$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2025-ii-hyaluronzuur-in-fillers-context11-uitwerkbijlage.png$$,
   $$uitwerkbijlage bij vraag 32: de structuurformule van de repeterende eenheid van HyZ met een pijl die de plaats van de hydrolyse aangeeft, gevolgd door ‘+ …→’ en twee lege reactievakken gescheiden door een ‘+’; de leerling moet de reactievergelijking van de hydrolyse met structuurformules van de koolstofverbindingen aanvullen.$$, 'uitwerkbijlage'),
  ('8e74869b-987a-4f5f-b2a9-f78d8c871312', '7c680bd1-f008-4134-8937-2b80ce5b52d4', $$uitwerkbijlage vraag 33 — assenstelsel molaire massa tegen tijd$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2025-ii-hyaluronzuur-in-fillers-context12-uitwerkbijlage.png$$,
   $$uitwerkbijlage bij vraag 33: een leeg assenstelsel (identiek aan figuur 2) met op de y-as de molaire massa van HyZ (g mol⁻¹, van 15,0·10³ tot 17,0·10³) en op de x-as de tijd in dagen (0 tot 200); de leerling moet hierop het verloop schetsen van de molaire massa van HyZ als de filler in de koelkast wordt bewaard.$$, 'uitwerkbijlage');

insert into practice_questions (id, exercise_id, question_number, topics, keywords, question_summary, question_image_url, question_text, context_block_ids) values
  ('eba5ea50-b00f-4914-9dc1-c470ccc0158d', 'a1100036-e6b9-4770-96eb-2a27454008b5', 1,
   '[{"domain": "Reacties", "subdomain": "Chemische processen"}, {"domain": "Technologie en duurzaamheid", "subdomain": "Industriële processen en groene chemie"}]'::jsonb,
   '["reactievergelijking optellen", "atoomeconomie", "nitrobenzeenproces", "aniline", "benzeen"]'::jsonb,
   $$Opstellen van de totale reactievergelijking en berekenen van de atoomeconomie van het nitrobenzeenproces voor aniline.$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2025-ii-bacterien-maken-aniline-uit-suiker-vraag1.png$$, $$− Geef de totale vergelijking voor de productie van aniline uit benzeen via het nitrobenzeenproces.
− Bereken de atoomeconomie van het nitrobenzeenproces.$$, array['bed5c2d5-d6ed-499a-b109-02485f01b8be']::uuid[]),
  ('5346fa83-bab4-4c0c-8c23-94a869c94fa1', 'a1100036-e6b9-4770-96eb-2a27454008b5', 2,
   '[{"domain": "Technologie en duurzaamheid", "subdomain": "Industriële processen en groene chemie"}]'::jsonb,
   '["groene chemie", "veiligheid", "salpeterzuur", "gevaarlijke stof"]'::jsonb,
   $$Uitleggen waarom het gebruik van geconcentreerd salpeterzuur niet voldoet aan uitgangspunt 12 van de groene chemie.$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2025-ii-bacterien-maken-aniline-uit-suiker-vraag2.png$$, $$Leg uit dat het gebruik van geconcentreerd salpeterzuur niet bij uitgangspunt 12 van de groene chemie past.$$, array['119e6973-d42e-4aa6-abea-35b0676c26ef']::uuid[]),
  ('364ced40-79b9-486d-9155-faa5163f6b68', 'a1100036-e6b9-4770-96eb-2a27454008b5', 3,
   '[{"domain": "Rekenen en analyse", "subdomain": "Grootheden en relaties"}]'::jsonb,
   '["pH", "pOH", "hydroxide-ionen", "significante cijfers"]'::jsonb,
   $$Berekenen van de concentratie hydroxide-ionen bij een gegeven pH.$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2025-ii-bacterien-maken-aniline-uit-suiker-vraag3.png$$, $$Bereken [OH⁻] in mol L⁻¹ bij pH = 7,5 (T = 298 K). Geef je antwoord in het juiste aantal significante cijfers.$$, array['722c735e-4bc7-4181-8bea-efa7918a2120']::uuid[]),
  ('b9bbc0e9-020b-483f-bf5c-0b7d726f887b', 'a1100036-e6b9-4770-96eb-2a27454008b5', 4,
   '[{"domain": "Reacties", "subdomain": "Chemische processen"}]'::jsonb,
   '["anthraniline", "zuur-base", "carbonzuurgroep", "structuurformule"]'::jsonb,
   $$Aanwijzen welk H-atoom van anthraniline als H⁺-ion wordt afgestaan bij een gegeven pH.$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2025-ii-bacterien-maken-aniline-uit-suiker-vraag4.png$$, $$Omcirkel in de figuur op de uitwerkbijlage welk H-atoom van anthraniline als H⁺-ion is afgestaan bij pH = 7,5.$$, array['8907a151-a21d-4e93-a8f9-f6b73717df76', '722c735e-4bc7-4181-8bea-efa7918a2120', '45da9ac2-edc5-47e8-a589-fc65ac0512d3']::uuid[]),
  ('a856809b-4d33-48ff-aa10-b6814a5f8a3b', 'a1100036-e6b9-4770-96eb-2a27454008b5', 5,
   '[{"domain": "Materie", "subdomain": "Bindingen en eigenschappen"}]'::jsonb,
   '["vanderwaalsbinding", "waterstofbrug", "intermoleculaire binding", "aniline", "dodecaan-1-ol"]'::jsonb,
   $$Benoemen van de twee typen intermoleculaire bindingen tussen aniline en dodecaan-1-ol.$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2025-ii-bacterien-maken-aniline-uit-suiker-vraag5.png$$, $$Geef de twee bindingstypen die aanwezig zijn tussen moleculen aniline en moleculen dodecaan-1-ol.$$, array['929ad2bf-f17d-4ea0-a9c3-8122baf58817']::uuid[]),
  ('0adce7b3-5c51-4234-84b4-c3aa3b675350', 'a1100036-e6b9-4770-96eb-2a27454008b5', 6,
   '[{"domain": "Rekenen en analyse", "subdomain": "Chemische vakmethodes"}]'::jsonb,
   '["dichtheid", "vloeistoflagen", "extractie", "stofeigenschap"]'::jsonb,
   $$Aangeven welk stofeigenschapverschil bepaalt dat de dodecaan-1-ollaag boven de waterlaag komt.$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2025-ii-bacterien-maken-aniline-uit-suiker-vraag6.png$$, $$Geef aan door welk verschil in stofeigenschap de laag met dodecaan-1-ol boven de waterlaag in S2 terechtkomt.$$, array['1b576370-f591-413f-9cea-dfd78344bd6e']::uuid[]),
  ('ce2757b6-2e78-422e-83fa-193b66d8aef2', 'a1100036-e6b9-4770-96eb-2a27454008b5', 7,
   '[{"domain": "Rekenen en analyse", "subdomain": "Chemische vakmethodes"}]'::jsonb,
   '["destilleren", "kookpunt", "scheidingsmethode"]'::jsonb,
   $$Bepalen en toelichten van de juiste scheidingsmethode voor dodecaan-1-ol en aniline op basis van kookpunt.$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2025-ii-bacterien-maken-aniline-uit-suiker-vraag7.png$$, $$Leg uit welke scheidingsmethode kan worden toegepast om dodecaan-1-ol en aniline te scheiden in S3.$$, array['c6313954-6b7d-41bf-b308-8ca83d47103c']::uuid[]),
  ('fa643e98-91a4-40bd-b579-7d70dd9b5e3d', 'a1100036-e6b9-4770-96eb-2a27454008b5', 8,
   '[{"domain": "Technologie en duurzaamheid", "subdomain": "Industriële processen en groene chemie"}]'::jsonb,
   '["blokschema", "stofstromen", "scheidingsproces", "hergebruik"]'::jsonb,
   $$Completeren van een blokschema van het aniline-productieproces met stofstromen en hergebruik van dodecaan-1-ol.$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2025-ii-bacterien-maken-aniline-uit-suiker-vraag8.png$$, $$Maak het blokschema op de uitwerkbijlage compleet.
− Teken de blokken S2 en S3.
− Teken de pijlen van de ontbrekende stofstromen bij R2, S2 en S3.
− Noteer de nummers van de onderstaande stoffen bij de juiste pijlen:
1 aniline
2 dodecaan-1-ol
3 koolstofdioxide
4 water
5 wateroplosbare bijproducten
− Je moet sommige nummers meer dan één keer gebruiken.
− Houd rekening met hergebruik van stoffen.
− Bij de voorgedrukte pijlen hoef je geen nummers te noteren.$$, array['8907a151-a21d-4e93-a8f9-f6b73717df76', '929ad2bf-f17d-4ea0-a9c3-8122baf58817', 'c6313954-6b7d-41bf-b308-8ca83d47103c', '89718979-56ba-4c25-97f8-85379f063b44']::uuid[]),
  ('ce3f9836-6b7d-412e-94b1-a33d56783b9e', '96432d5c-9443-4da5-95a7-bd5967d8556a', 9,
   '[{"domain": "Rekenen en analyse", "subdomain": "Grootheden en relaties"}]'::jsonb,
   '["molariteit", "concentratie", "molaire massa", "natrium-ionen"]'::jsonb,
   $$Omrekenen van de molariteit van Na⁺-ionen in zeewater naar een concentratie in gram per liter.$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2025-ii-zeewater-accu-vraag9.png$$, $$Bereken de concentratie van de Na⁺-ionen in zeewater in gram per liter.$$, array['576f3b64-7956-4397-80e6-22ebf86f3b88']::uuid[]),
  ('05dc44fa-1903-461a-ac33-22377944744b', '96432d5c-9443-4da5-95a7-bd5967d8556a', 10,
   '[{"domain": "Materie", "subdomain": "Deeltjesmodellen"}]'::jsonb,
